export const DEFAULT_PUBLIC_COPY = Object.fromEntries(
  PUBLIC_COPY_FIELDS.map(({ key, value }) => [key, value]),
) as Record<string, string>;

export function publicText(copy: Record<string, string> | undefined, key: string): string {
  return copy?.[key] ?? DEFAULT_PUBLIC_COPY[key] ?? '';
}
